create extension if not exists "pgcrypto";create table if not exists public.products(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,category text not null,price integer not null,description text not null,image text not null,created_at timestamptz default now());create table if not exists public.product_variants(id uuid primary key default gen_random_uuid(),product_id uuid references public.products(id) on delete cascade,size integer not null,color text not null,inventory integer not null default 0);create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz default now());create table if not exists public.orders(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete set null,status text not null default 'pending',total integer not null,created_at timestamptz default now());create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,quantity integer not null,unit_price integer not null,size integer);alter table public.products enable row level security;create policy "products public read" on public.products for select using(true);alter table public.product_variants enable row level security;create policy "variants public read" on public.product_variants for select using(true);alter table public.profiles enable row level security;create policy "profile owner read" on public.profiles for select using(auth.uid()=id);